INSERT INTO recipe_step (recipe_id, step_no, content, duration) VALUES (@rid, 1, '热锅放猪油化开，下姜片爆香（约 30 秒）', 1);
INSERT INTO recipe_step (recipe_id, step_no, content, duration) VALUES (@rid, 2, '鲫鱼下锅，中火煎到两面金黄（不要急着翻面，定型再翻）（约 4 分钟）', 4);
INSERT INTO recipe_step (recipe_id, step_no, content, duration) VALUES (@rid, 3, '沿锅边淋料酒去腥（约 10 秒）', 1);
INSERT INTO recipe_step (recipe_id, step_no, content, duration) VALUES (@rid, 4, '倒入开水！一定要开水，没过鱼身，大火滚煮（约 10 分钟）', 10);
INSERT INTO recipe_step (recipe_id, step_no, content, duration) VALUES (@rid, 5, '汤变奶白色后，捞出鱼和姜片（鱼可单独吃或拆肉回汤）（约 30 秒）', 1);
INSERT INTO recipe_step (recipe_id, step_no, content, duration) VALUES (@rid, 6, '汤里加盐调味，保持微滚（约 30 秒）', 1);
INSERT INTO recipe_step (recipe_id, step_no, content, duration) VALUES (@rid, 7, '另起锅烧水煮面，面条煮到断生（没有白芯）（约 3 分钟）', 3);
INSERT INTO recipe_step (recipe_id, step_no, content, duration) VALUES (@rid, 8, '面捞入碗中，浇上滚烫的鱼汤，撒葱花、白胡椒粉、虾籽，开吃！（约 1 分钟）', 1);
